class EnvironmentClient(ManagementClient):
    """Cbox ID — Environment Management API.

    The **per-environment management plane** — the API an app's own backend uses to run
    its tenancy inside ONE environment: organizations and their owners, members,
    invitations, roles (in one organization, or everywhere for your staff), apps, APIs,
    the API keys customers made for them, and support sessions. It is served on
    the environment's own host ({slug}.cboxid.com or a custom domain): the host pins
    the environment, and the request is authenticated with an environment API key
    (`cbid_env_…`).

    ``base_url`` is required: the environment's own host.
    """

    _plane = "environment"

    def _bind(self, core: ManagementTransport) -> None:
        self.access_reviews = AccessReviewsMethods(core)
        self.action_approvals = ActionApprovalsMethods(core)
        self.api_keys = ApiKeysMethods(core)
        self.apis = ApisMethods(core)
        self.approvals = ApprovalsMethods(core)
        self.apps = AppsMethods(core)
        self.audit = AuditMethods(core)
        self.audit_logs = AuditLogsMethods(core)
        self.branding = BrandingMethods(core)
        self.directories = DirectoriesMethods(core)
        self.domains = DomainsMethods(core)
        self.events = EventsMethods(core)
        self.feature_flags = FeatureFlagsMethods(core)
        self.fga = FgaMethods(core)
        self.frontend_keys = FrontendKeysMethods(core)
        self.hooks = HooksMethods(core)
        self.invitations = InvitationsMethods(core)
        self.keys = KeysMethods(core)
        self.legacy_login = LegacyLoginMethods(core)
        self.log_streams = LogStreamsMethods(core)
        self.members = MembersMethods(core)
        self.organizations = OrganizationsMethods(core)
        self.permissions = PermissionsMethods(core)
        self.pipes = PipesMethods(core)
        self.provisioning = ProvisioningMethods(core)
        self.radar = RadarMethods(core)
        self.roles = RolesMethods(core)
        self.saml_apps = SamlAppsMethods(core)
        self.signin = SigninMethods(core)
        self.sod_policies = SodPoliciesMethods(core)
        self.sso = SsoMethods(core)
        self.support_sessions = SupportSessionsMethods(core)
        self.token_vault = TokenVaultMethods(core)
        self.users = UsersMethods(core)
        self.webhooks = WebhooksMethods(core)
